ull,"minima":1,"incluida":null,"adicional":0,"ufs":[]},{"nome":"Laser CO2 Fracionado – Assistido 8 horas","nomes":["Laser CO2 Fracionado – Assistido 8 horas"],"familia":"Laser CO2 Fracionado","categoria":"ESTETICA","descricao":"CO2 Day Assistido, 8 horas: tudo do Essencial + profissional Hemoderi (biomédico esteta ou dentista especialista) na sala. Equipamento Fraxion SmartGR com ponteiras fracionadas, cirúrgicas e íntimas, insumos, EPIs, logística, montagem e desmontagem.","duracao":480,"valor":249000,"exige":true,"tipo":"Laser CO2 Fracionado","unidade":"PERIODO","permite":false,"rotulo":null,"minima":1,"incluida":null,"adicional":0,"ufs":[]},{"nome":"Laser CO2 Fracionado – CO2 Curso (por paciente)","nomes":["Laser CO2 Fracionado – CO2 Curso (por paciente)"],"familia":"Laser CO2 Fracionado","categoria":"ESTETICA","descricao":"CO2 Curso, valor por paciente — desconto exclusivo para o serviço CO2 Fracionado. Equipamento Fraxion SmartGR com ponteiras fracionadas, cirúrgicas e íntimas, insumos, EPIs, logística, montagem e desmontagem.","duracao":60,"valor":49000,"exige":true,"tipo":"Laser CO2 Fracionado","unidade":"PACIENTE","permite":false,"rotulo":null,"minima":1,"incluida":null,"adicional":0,"ufs":[]}]$json$::jsonb) LOOP
    UPDATE "Servico" SET
      "nome" = r->>'nome',
      "familia" = r->>'familia',
      "categoria" = (r->>'categoria')::"CategoriaServico",
      "descricao" = r->>'descricao',
      "duracaoMin" = (r->>'duracao')::int,
      "valorPadraoCentavos" = (r->>'valor')::int,
      "exigeEquipamento" = (r->>'exige')::boolean,
      "tipoEquipamento" = r->>'tipo',
      "unidadeCobranca" = (r->>'unidade')::"UnidadeCobranca",
      "permiteQuantidade" = (r->>'permite')::boolean,
      "rotuloQuantidade" = r->>'rotulo',
      "quantidadeMinima" = (r->>'minima')::int,
      "quantidadeIncluida" = (r->>'incluida')::int,
      "valorAdicionalCentavos" = (r->>'adicional')::int,
      "ufsIndisponiveis" = ARRAY(SELECT jsonb_array_elements_text(r->'ufs')),
      "ativo" = true, "desativadoEm" = NULL, "atualizadoEm" = NOW()
    WHERE "id" = (
      SELECT "id" FROM "Servico"
      WHERE "nome" = ANY(ARRAY(SELECT jsonb_array_elements_text(r->'nomes')))
      ORDER BY ("nome" = r->>'nome') DESC, "criadoEm" LIMIT 1
    );

    IF NOT FOUND THEN
      INSERT INTO "Servico" (
        "id", "nome", "familia", "categoria", "descricao", "duracaoMin", "valorPadraoCentavos",
        "exigeEquipamento", "tipoEquipamento", "unidadeCobranca", "permiteQuantidade", "rotuloQuantidade",
        "quantidadeMinima", "quantidadeIncluida", "valorAdicionalCentavos", "ufsIndisponiveis",
        "ativo", "criadoEm", "atualizadoEm"
      ) VALUES (
        gen_random_uuid()::text, r->>'nome', r->>'familia', (r->>'categoria')::"CategoriaServico", r->>'descricao',
        (r->>'duracao')::int, (r->>'valor')::int, (r->>'exige')::boolean, r->>'tipo',
        (r->>'unidade')::"UnidadeCobranca", (r->>'permite')::boolean, r->>'rotulo',
        (r->>'minima')::int, (r->>'incluida')::int, (r->>'adicional')::int,
        ARRAY(SELECT jsonb_array_elements_text(r->'ufs')), true, NOW(), NOW()
      );
    END IF;
  END LOOP;

  -- Saiu do catálogo atual: desativado, nunca apagado (pedidos antigos apontam para ele).
  UPDATE "Servico" SET "ativo" = false, "desativadoEm" = NOW(), "atualizadoEm" = NOW()
   WHERE "nome" = ANY(ARRAY(SELECT jsonb_array_elements_text($json$["PRF – Coleta e Produção de Concentrados Plaquetários","AirFlow – GBT Machine (pacote 9 pacientes)","Ultrassom Atria® – Tratamento Facial","Ultrassom Atria® – Tratamento Corporal","Ultrassom Atria® – Facial 900 disparos (4 h)","Ultrassom Atria® – Facial 1600 disparos (8 h)","Ultrassom Atria® – Facial 3000 disparos (8 h)","Ultrassom Atria® – Facial 5000 disparos (12 h)","Ultrassom Atria® – Facial 7000 disparos (12 h)"]$json$::jsonb))) AND "ativo";
